async function exportWav(){try{await context();let buffer;if(state.source.kind==='demo'){await ensureDemo();buffer=audioCtx.createBuffer(2,demoStems.lead.length,32000);for(let c=0;c<2;c++){let out=buffer.getChannelData(c);for(const[key,b]of Object.entries(demoStems)){let gain=state.mute[key]||state.solo&&state.solo!==key?0:10**(state.mix[key]/20),d=b.getChannelData(c);for(let i=0;i<out.length;i++)out[i]+=d[i]*gain;}}}else{if(!decoded){toast('请先重新链接原始音频。');return;}buffer=decoded;}state.selection=normalizeSelection(state.selection,state.source.duration);let start=state.exportRange==='selection'?Math.floor(state.selection[0]*buffer.sampleRate):0,end=state.exportRange==='selection'?Math.min(buffer.length,Math.floor(state.selection[1]*buffer.sampleRate)):buffer.length,n=Math.max(0,end-start),ch=buffer.numberOfChannels,b=new ArrayBuffer(44+n*ch*2),v=new DataView(b),str=(at,s)=>{for(let i=0;i<s.length;i++)v.setUint8(at+i,s.charCodeAt(i));};str(0,'RIFF');v.setUint32(4,36+n*ch*2,true);str(8,'WAVE');str(12,'fmt ');v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,ch,true);v.setUint32(24,buffer.sampleRate,true);v.setUint32(28,buffer.sampleRate*ch*2,true);v.setUint16(32,ch*2,true);v.setUint16(34,16,true);str(36,'data');v.setUint32(40,n*ch*2,true);let gain=state.mute.master||(state.source.kind!=='demo'&&state.mute.source)?0:10**((state.mix.master+(state.source.kind==='demo'?0:state.mix.source||0))/20),clipped=0,channels=Array.from({length:ch},(_,c)=>buffer.getChannelData(c));for(let i=0;i<n;i++)for(let c=0;c<ch;c++){let val=channels[c][i+start]*gain;if(Math.abs(val)>1)clipped++;val=clamp(val,-1,1);v.setInt16(44+(i*ch+c)*2,val<0?val*32768:val*32767,true);}if(clipped){openModal('总线增益过高',`<p>当前设置有 ${clipped} 个输出采样值超出 PCM 范围。请降低总线增益后再导出，避免裁切失真。</p>`);return;}download(state.source.kind==='demo'?'sonora-synthetic-demo.wav':'sonora-original-trim-preview.wav',new Blob([b],{type:'audio/wav'}));toast('已按解码采样率导出 16 bit WAV；未包含 AI 转换。');}catch(e){toast('导出失败：'+e.message);}}
function openModal(title,body,footerHtml=''){stopAudio();$('#modalContent').innerHTML=`<div class="modal-top"><h2>${esc(title)}</h2><button class="icon-button" data-act="closeModal" aria-label="关闭对话框">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-footer">${footerHtml}<button class="button primary" data-act="closeModal">知道了</button></div>`;$('#modal').showModal();}
function about(){openModal('这是一个可操作的产品原型',`<h3>可以真实操作</h3><p>本地音频导入、解码、播放、波形选区、循环、合成示例分轨的静音/独奏与音量、裁剪与总线增益 WAV 导出、歌词/音符交互、配方 JSON 导入导出、撤销。</p><h3>用于展示设计</h3><p>AI 分离、F0 算法、歌词识别、模型推理、EQ/压缩/混响、多模型候选与任务进度均为明确标注的演示。候选 B 仅提供合成示例的滤波对照，不代表任何模型音质。</p><h3>正式版的能力边界</h3><p>推理引擎在本地桌面执行器运行；网页负责编辑与试听。换音色、修音准和改歌词分别处理，模型能力检查决定可用参数。</p><p>快捷键：空格播放 / 暂停；Ctrl / ⌘ + Z 撤销；选中示例音符后用 ↑ ↓ 移动。文件内容不会上传。</p>`);}
function queueJob(title,candidate=false){snapshot();let params={model:state.model,alg:state.alg,indexRate:state.indexRate,shift:state.shift,source:state.serial?state.selectedVersion:'clean'};let now=Date.now(),id='job'+now;state.jobs.push({id,title,detail:'准备演示状态 · 不调用推理引擎',status:'queued',started:now,phase:0,candidate,params});if(!jobTimer)jobTimer=setInterval(advanceJobs,700);activePanel='queue';render();toast('已创建演示任务，可在队列中取消。');}
function advanceJobs(){let job=state.jobs.find(j=>j.status==='running')||state.jobs.find(j=>j.status==='queued');if(!job){clearInterval(jobTimer);jobTimer=null;return;}job.status='running';job.phase++;let labels=['检查示例配方','复用已确认编辑 · 状态演示','派发处理步骤 · 状态演示','登记示例候选 · 不生成模型音频'];job.detail=labels[Math.min(job.phase-1,3)];if(job.phase>=6){job.status='done';job.detail='演示完成 · 没有模型推理音频';if(job.candidate){let id='v'+String(state.versions.length+1).padStart(2,'0');state.versions.push({id,label:'试听实验 · '+id.toUpperCase(),...job.params,type:'demo'});state.selectedVersion=id;}toast('任务演示完成；可查看候选参数，未生成 AI 音频。');}if(activePanel==='queue')render();else{$('#queueCount').textContent=state.jobs.filter(j=>['queued','running'].includes(j.status)).length;$('#versionCount').textContent=state.versions.length;}}
function adjustNote(dir){if(state.pitchLocked){toast('手动区已锁定，请先解锁。');return;}snapshot();let i=state.selectedNote??8;state.selectedNote=i;state.pitchEdits[i]=clamp((state.pitchEdits[i]??melody[i])+dir,45,85);drawPitch();if($('#selectedNoteLabel'))$('#selectedNoteLabel').textContent='· 音符 '+(i+1);toast(`示例音符 ${i+1} ${dir>0?'升高':'降低'}一个半音。此编辑保存到配方。`);}
function undo(){
 if(!undoStack.length){toast('没有可撤销的编辑。');return;}
 stopAudio(true);loadEpoch++;state=JSON.parse(undoStack.pop());
 if(state.source.kind==='demo')decoded=null;
 else{decoded=audioCache.get(state.source.id)||null;state.source.kind=decoded?'local':'unlinked';}
 state.selection=normalizeSelection(state.selection,state.source.duration);listen='A';render();applyGains();toast('已撤销最近一次编辑。');
}
document.addEventListener('click',async e=>{let b=e.target.closest('button,a.brand');if(!b)return;if(b.matches('a.brand')){e.preventDefault();goStep(0);return;}if(b.dataset.step!==undefined){goStep(Number(b.dataset.step));return;}if(b.dataset.mode){state.mode=b.dataset.mode;render();return;}if(b.dataset.panel){activePanel=b.dataset.panel;render();return;}if(b.dataset.task){snapshot();state.task=b.dataset.task;if(state.task==='speech'){state.preset='speech';Object.assign(state,presets.speech);}if(state.task==='lyrics')state.pitchTab='lyrics';activePanel=null;render();return;}if(b.dataset.pitchtab){state.pitchTab=b.dataset.pitchtab;render();return;}if(b.dataset.tool){state.tool=b.dataset.tool;render();return;}if(b.dataset.alg){snapshot();state.alg=b.dataset.alg;render();return;}if(b.dataset.route){snapshot();state.lyricsRoute=b.dataset.route;render();return;}if(b.dataset.format){state.format=b.dataset.format;render();return;}if(b.dataset.version){state.selectedVersion=b.dataset.version;render();return;}if(b.dataset.restoreversion){let v=state.versions.find(v=>v.id===b.dataset.restoreversion);if(v){snapshot();Object.assign(state,{model:v.model,alg:v.alg,indexRate:v.indexRate,shift:v.shift});state.selectedVersion=v.id;toast('已恢复此候选的转换参数。');render();}return;}if(b.dataset.preview){openModal('候选试听说明','<p>当前候选只保存演示参数，没有模型生成的音频。底部 A/B 可试听合成示例的原声与滤波对照，展示切换交互。</p>','<button class="button" data-act="demoAB">试听合成 A/B</button>');return;}if(b.dataset.selectmodel){snapshot();state.model=b.dataset.selectmodel;render();return;}if(b.dataset.toggle){snapshot();let k=b.dataset.toggle;if(k.startsWith('post.'))state.post[k.split('.')[1]]=!state.post[k.split('.')[1]];else state[k]=!(state[k]??(['breaths','retainTiming','melisma'].includes(k)));render();return;}if(b.dataset.mute){snapshot();state.mute[b.dataset.mute]=!state.mute[b.dataset.mute];render();applyGains();return;}if(b.dataset.solo){snapshot();state.solo=state.solo===b.dataset.solo?null:b.dataset.solo;render();applyGains();return;}if(b.dataset.cancel){let j=state.jobs.find(j=>j.id===b.dataset.cancel);if(j){j.status='cancelled';j.detail='由用户取消 · 无模型产物';render();}return;}
  switch(b.dataset.act){case'import':$('#audioInput').click();break;case'demo':stopAudio(true);loadEpoch++;snapshot();state.source=newState().source;state.selection=[12,16];decoded=null;state.mute={};state.solo=null;render();toast('已载入合成示例，可试听三条独立声轨。');break;case'next':goStep(state.step+1);break;case'prev':goStep(state.step-1);break;case'pitch':state.pitchTab='pitch';goStep(2);break;case'convert':goStep(3);break;case'backWorkspace':activePanel=null;render();break;case'about':about();break;case'undo':undo();break;case'closeModal':$('#modal').close();break;case'saveRecipe':saveRecipe();break;case'importRecipe':$('#recipeInput').click();break;case'exportWav':await exportWav();break;case'listenRisk':state.selection=[state.source.duration*.5,state.source.duration*2/3];case'playSelection':stopAudio();state.loop=true;offset=state.selection[0];await playAudio();drawWaves();break;case'resetSelection':snapshot();state.selection=[0,state.source.duration];render();break;case'simulateSeparation':queueJob('主唱 / 和声分离 · 演示');break;case'reviewPitch':snapshot();state.pitchFixed=true;render();toast('已采纳示例主旋律修复；手动编辑保持。实际算法未执行。');break;case'resetPitch':snapshot();state.pitchFixed=false;render();break;case'lockPitch':snapshot();state.pitchLocked=!state.pitchLocked;render();break;case'noteUp':adjustNote(1);break;case'noteDown':adjustNote(-1);break;case'runCandidate':queueJob('选区多模型候选 · 演示',true);break;case'runFull':queueJob('整曲转换流程 · 演示',true);break;case'demoAB':$('#modal').close();if(state.source.kind!=='demo'){toast('请先在导入页切换到合成示例。');break;}switchListen('B');if(!isPlaying)await playAudio();break;case'lyricsPreview':openModal('这一句如何变成新演唱',`<h3>第 1 句 · ${esc(state.lyrics[0])}</h3><p>${state.lyricsRoute==='guide'?'1. 录制或导入唱着新词的干声。<br>2. 对齐句子边界并修正旋律。<br>3. 用已训练的 VC 模型转换目标音色。':'1. 确认旋律、音符时长与音素映射。<br>2. 使用兼容的 SVS 引擎合成新词导唱。<br>3. 需要时再用已训练的 VC 模型转换目标音色。'}</p><p>原型只展示执行计划。没有新的演唱音频时，不会假称“歌词已替换”。</p>`);break;case'modelImportPlan':openModal('导入已有训练模型','<p>1. 选择模型权重与配套配置、索引。<br>2. 识别架构，校验哈希、来源与许可证。<br>3. 检查执行器、编码器、采样率和设备。<br>4. 用短片段验证实际能力，再登记模型。</p><p>缺少索引时明确选择补齐索引或关闭检索。未知权重不直接在主进程加载。原型不会接收或执行模型文件。</p>');break;case'tuning':openModal('把调优变成一次小实验','<h3>推理调参</h3><p>移调、检索比例、清辅音保护、音量包络、切片长度与上下文；只显示当前执行器支持的参数。</p><h3>候选搜索</h3><p>选高低音、气声和难句；设置最多候选数和算力预算；每个候选从同一干净源生成，做对齐、等响度试听，人工选优。</p><h3>训练 / 微调</h3><p>作为独立高级区：数据质检、切分、训练/验证划分、checkpoint 管理、固定验证句、过拟合观察和回滚。已有模型用户无需进入。</p>');break;case'realtimePlan':openModal('实时模式执行方案','<p>音频设备回调 → 有界环形缓冲 → 流式前处理 / VC Worker → 对齐交叠 → 输出设备。</p><p>音频线程不等待界面、模型下载、离线任务或磁盘操作。切换音色先预热；显存不足时采用明确的停顿切换。</p><p>首次使用实测端到端延迟、丢帧率和可用块长。虚拟声卡安装单独引导，设备授权不混入模型下载。</p>');break;}
});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='trimStart'||el.id==='trimEnd'){let a=Number($('#trimStart').value),b=Number($('#trimEnd').value);if($('#trimStart').value!==''&&$('#trimEnd').value!==''&&Number.isFinite(a)&&Number.isFinite(b)&&a>=0&&b<=state.source.duration&&b>a){state.selection=[a,b];if($('#selectionText'))$('#selectionText').textContent=time(a)+' — '+time(b);drawWaves();}}if(el.dataset.range){let k=el.dataset.range;state[k]=Number(el.value);let out=$('#'+k+'Value');if(out)out.textContent=el.value+(el.dataset.suffix||'');if(['shift','vibrato','correction'].includes(k))drawPitch();}if(el.dataset.mix){state.mix[el.dataset.mix]=Number(el.value);$('#mixLabel'+el.dataset.mix).textContent=(el.value>0?'+':'')+Number(el.value).toFixed(1)+' dB';applyGains();}if(el.dataset.lyric!==undefined){let i=Number(el.dataset.lyric);state.lyrics[i]=el.value;let out=$('#lyricCount'+i);out.textContent=lyricCount(el.value,i);out.classList.toggle('warn',el.value.replace(/\s/g,'').length!==originalLyrics[i].length);}});
document.addEventListener('focusin',e=>{if(e.target.matches('[data-range],[data-mix],[data-lyric],#trimStart,#trimEnd'))snapshot();});
document.addEventListener('change',e=>{let el=e.target;if(el.dataset.field){snapshot();let k=el.dataset.field;state[k]=el.value;if(k==='preset'){let p=presets[el.value];Object.assign(state,{shift:p.shift,correction:p.correction,vibrato:p.vibrato,indexRate:p.indexRate,protect:p.protect});toast('已应用预设，可继续调整。');}render();}if(el.id==='trimStart'||el.id==='trimEnd'){let a=Number($('#trimStart').value),b=Number($('#trimEnd').value);if(!Number.isFinite(a)||!Number.isFinite(b)||a<0||b>state.source.duration||b<=a){toast('选区需满足 0 ≤ 起点 < 终点 ≤ 音频时长。');render();return;}snapshot();state.selection=[a,b];render();}if(el.dataset.check){state.checks||={};state.checks[el.dataset.check]=el.checked;}});
document.addEventListener('pointerdown',e=>{let c=e.target;if(c.matches('.wave')){snapshot();let r=c.getBoundingClientRect(),t=clamp((e.clientX-r.left)/r.width,0,1)*state.source.duration;drag={type:'wave',canvas:c,start:t};c.setPointerCapture(e.pointerId);state.selection=[t,Math.min(t+.1,state.source.duration)];drawWaves();}if(c.id==='pitchCanvas'){let r=c.getBoundingClientRect(),x=clamp((e.clientX-r.left-34)/(r.width-48),0,.999),i=Math.floor(x*16);state.selectedNote=i;if(state.pitchLocked){drawPitch();toast('手动区已锁定。');return;}snapshot();drag={type:'pitch',canvas:c,index:i};c.setPointerCapture(e.pointerId);updatePitchPointer(e);}});
function updatePitchPointer(e){
 if(!drag||drag.type!=='pitch')return;
 const r=drag.canvas.getBoundingClientRect(),x=clamp((e.clientX-r.left-34)/(r.width-48),0,1);
 let m=57+(r.height-23-(e.clientY-r.top))/(r.height-41)*16-state.shift;
 if(state.tool==='select'){drawPitch();return;}
 if(state.tool==='draw'){
  const frame=Math.round(x*500);m=clamp(m,45,85);
  if(drag.lastFrame!==undefined){const lo=Math.min(frame,drag.lastFrame),hi=Math.max(frame,drag.lastFrame);for(let k=lo;k<=hi;k++){const t=(k-drag.lastFrame)/(frame-drag.lastFrame||1);state.curveEdits[k]=drag.lastPitch+t*(m-drag.lastPitch);}}
  else state.curveEdits[frame]=m;
  drag.lastFrame=frame;drag.lastPitch=m;
 }else state.pitchEdits[drag.index]=clamp(state.snap?Math.round(m):Math.round(m*10)/10,45,85);
 drawPitch();
}
document.addEventListener('pointermove',e=>{if(!drag)return;if(drag.type==='wave'){let r=drag.canvas.getBoundingClientRect(),t=clamp((e.clientX-r.left)/r.width,0,1)*state.source.duration;state.selection=[Math.min(drag.start,t),Math.max(drag.start,t)];drawWaves();}else updatePitchPointer(e);});
document.addEventListener('pointerup',()=>{if(!drag)return;let type=drag.type;drag=null;if(type==='wave'){state.selection=normalizeSelection(state.selection,state.source.duration);if($('#selectionText'))$('#selectionText').textContent=time(state.selection[0])+' — '+time(state.selection[1]);if($('#trimStart'))$('#trimStart').value=state.selection[0].toFixed(1);if($('#trimEnd'))$('#trimEnd').value=state.selection[1].toFixed(1);}else render();});
$('#playButton').addEventListener('click',playAudio);$('#startButton').addEventListener('click',()=>{let was=isPlaying;stopAudio();offset=state.loop?state.selection[0]:0;updatePlayer();if(was)playAudio();});$('#loopButton').addEventListener('click',()=>{state.loop=!state.loop;updatePlayer();toast(state.loop?'循环已开启：当前时间选区。':'循环已关闭。');});$('#seek').addEventListener('input',e=>{const was=isPlaying;stopAudio();offset=Number(e.target.value);updatePlayer();if(was)playAudio();});$('#masterVolume').addEventListener('input',applyGains);$('#listenOriginal').addEventListener('click',()=>switchListen('A'));$('#listenCandidate').addEventListener('click',()=>switchListen('B'));$('#audioInput').addEventListener('change',e=>{loadAudio(e.target.files[0]);e.target.value='';});$('#recipeInput').addEventListener('change',e=>{if(e.target.files[0])importRecipe(e.target.files[0]);e.target.value='';});$('#aboutButton').addEventListener('click',about);$('#saveButton').addEventListener('click',saveRecipe);$('#undoButton').addEventListener('click',undo);$('#projectPicker').addEventListener('click',()=>openModal('工程与素材','<p>工程配方保存任务选择、编辑参数、歌词、模型候选与时间选区。原始音频在本机内存中，不会上传，也不会随网页自动保存。</p><p>可导出配方后重新打开，或继续导入一条原始音频开始制作。</p>','<button class="button" data-act="saveRecipe">保存配方</button><button class="button" data-act="importRecipe">导入配方</button>'));document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||$('#modal').open)return;if(e.code==='Space'){e.preventDefault();playAudio();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undo();}if(state.step===2&&state.pitchTab==='pitch'&&['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();adjustNote(e.key==='ArrowUp'?1:-1);}});window.addEventListener('resize',()=>{drawWaves();drawPitch();});
render();
